//! Conformance tests for TSCP-CANON-001.
//!
//! These read the published fixture manifest and assert that this
//! implementation reproduces every published digest, and rejects every
//! case the manifest marks as a rejection, for the stated reason.
//!
//! The manifest is generated by `reference_canon.py` (the independent
//! Python oracle) and committed under `conformance/canon/fixtures/`.
//! A green run therefore means: two independent implementations agree.

use serde_json::Value;
use std::fs;
use std::path::PathBuf;
use tscp_canon::canonical::canonicalize_bytes;
use tscp_canon::hash::sha256_hex;

fn fixtures_root() -> PathBuf {
    // crate lives at <repo>/tools/tscp-canon
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .join("conformance/canon/fixtures")
}

fn manifest() -> Value {
    let path = fixtures_root().join("manifest.json");
    let text = fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read manifest at {}: {e}", path.display()));
    serde_json::from_str(&text).expect("manifest must be valid JSON")
}

fn cases() -> Vec<Value> {
    manifest()["test_cases"]
        .as_array()
        .expect("test_cases must be an array")
        .clone()
}

fn input_value(case: &Value) -> Value {
    let rel = case["input_file"].as_str().expect("input_file required");
    let path = fixtures_root().join(rel);
    let text = fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read input {}: {e}", path.display()));
    serde_json::from_str(&text).expect("input fixture must be valid JSON")
}

#[test]
fn manifest_is_populated_and_covers_both_outcomes() {
    let c = cases();
    assert!(
        c.len() >= 15,
        "manifest has only {} cases; an empty or shrunken manifest would let this suite pass vacuously",
        c.len()
    );
    let rejects = c
        .iter()
        .filter(|k| k["status"].as_str() == Some("REJECT"))
        .count();
    let accepts = c
        .iter()
        .filter(|k| k["status"].as_str().unwrap_or("SUCCESS") == "SUCCESS")
        .count();
    assert!(rejects > 0, "manifest declares no rejection cases");
    assert!(accepts > 0, "manifest declares no success cases");
}

#[test]
fn every_success_case_reproduces_the_published_digest() {
    let mut checked = 0usize;
    for case in cases() {
        if case["status"].as_str().unwrap_or("SUCCESS") != "SUCCESS" {
            continue;
        }
        let id = case["id"].as_str().unwrap_or("<unknown>");
        let expected = case["expected_sha256"]
            .as_str()
            .unwrap_or_else(|| panic!("{id}: expected_sha256 required"));
        let bytes = canonicalize_bytes(&input_value(&case))
            .unwrap_or_else(|e| panic!("{id}: canonicalization failed unexpectedly: {e}"));
        assert_eq!(
            sha256_hex(&bytes),
            expected,
            "{id}: digest differs from the published fixture"
        );
        checked += 1;
    }
    assert!(checked > 0, "no success cases were checked");
}

#[test]
fn every_reject_case_is_rejected_for_the_stated_reason() {
    let mut checked = 0usize;
    for case in cases() {
        if case["status"].as_str() != Some("REJECT") {
            continue;
        }
        let id = case["id"].as_str().unwrap_or("<unknown>");
        let code = case["error_code"].as_str().expect("error_code required");
        let stage = case["error_stage"].as_str().expect("error_stage required");
        match canonicalize_bytes(&input_value(&case)) {
            Ok(_) => panic!("{id}: expected rejection ({code}) but canonicalization succeeded"),
            Err(e) => {
                assert_eq!(e.code, code, "{id}: rejected with the wrong error code");
                assert_eq!(e.stage.as_str(), stage, "{id}: rejected at the wrong stage");
            }
        }
        checked += 1;
    }
    assert!(checked > 0, "manifest declares no rejection cases to check");
}

#[test]
fn output_ignores_input_key_order() {
    let a: Value = serde_json::from_str(r#"{"b": 2, "a": 1, "c": {"y": 2, "x": 1}}"#).unwrap();
    let b: Value = serde_json::from_str(r#"{"c": {"x": 1, "y": 2}, "a": 1, "b": 2}"#).unwrap();
    let da = sha256_hex(&canonicalize_bytes(&a).expect("canonicalize a"));
    let db = sha256_hex(&canonicalize_bytes(&b).expect("canonicalize b"));
    assert_eq!(da, db, "key order changed the canonical digest");
}

#[test]
fn distinct_inputs_produce_distinct_digests() {
    // Negative control: if canonicalize_bytes ever returned a constant,
    // every fixture digest would match and this suite would still be green.
    let a: Value = serde_json::from_str(r#"{"amount": 1999}"#).unwrap();
    let b: Value = serde_json::from_str(r#"{"amount": 2000}"#).unwrap();
    let da = sha256_hex(&canonicalize_bytes(&a).expect("canonicalize a"));
    let db = sha256_hex(&canonicalize_bytes(&b).expect("canonicalize b"));
    assert_ne!(da, db, "different inputs produced the same digest");
}
